// Worker entry: one origin for the API and the web (map #86, spike #90). The API paths go to
// the Hono application of apps/server; everything else is the Next.js application built by
// OpenNext (`opennextjs-cloudflare build` writes ./.open-next/worker.js before wrangler bundles
// this file).
import "./install-self-fetch";

import {
	apiFetch,
	apiQueue,
	apiScheduled,
	isApiPath,
	type WorkerContext,
	type WorkerEnv,
} from "server/worker";
// @ts-expect-error generated by `opennextjs-cloudflare build`, absent from the source tree
import openNext from "./.open-next/worker.js";
import { withSelf } from "./self-fetch";

// @ts-expect-error same generated file: Durable Object classes, when OpenNext configures any
export * from "./.open-next/worker.js";

export default {
	async fetch(
		request: Request,
		env: WorkerEnv,
		ctx: WorkerContext,
	): Promise<Response> {
		const url = new URL(request.url);
		if (isApiPath(url.pathname)) {
			return apiFetch(request, env, ctx);
		}
		return withSelf(
			url.origin,
			(self) => apiFetch(self, env, ctx),
			() => openNext.fetch(request, env, ctx),
		);
	},
	// Cron Triggers (apps/web/wrangler.jsonc): drain the outbox every minute (#259), read the watch
	// feed's Sources every half hour (#255).
	async scheduled(
		event: { cron?: string },
		env: WorkerEnv,
		ctx: WorkerContext,
	): Promise<void> {
		await apiScheduled(env, ctx, event.cron);
	},
	// Cloudflare Queues consumer of the outbox's events (#259).
	async queue(
		batch: Parameters<typeof apiQueue>[0],
		env: WorkerEnv,
	): Promise<void> {
		await apiQueue(batch, env);
	},
};
